class Solution {
  private static long linear(long[] cost, int from, int to, int need) {
    long INF = Long.MAX_VALUE / 4;
    if (need == 0) return 0;
    if (from > to) return INF;
    long[] skip = new long[need + 1], take = new long[need + 1];
    java.util.Arrays.fill(skip, INF);
    java.util.Arrays.fill(take, INF);
    skip[0] = 0;
    for (int i = from; i <= to; i++) {
      long[] nSkip = new long[need + 1], nTake = new long[need + 1];
      java.util.Arrays.fill(nSkip, INF);
      java.util.Arrays.fill(nTake, INF);
      for (int j = 0; j <= need; j++) {
        nSkip[j] = Math.min(skip[j], take[j]);
        if (j > 0 && skip[j - 1] < INF) nTake[j] = skip[j - 1] + cost[i];
      }
      skip = nSkip;
      take = nTake;
    }
    return Math.min(skip[need], take[need]);
  }

  public int minOperations(int[] nums, int k) {
    int n = nums.length;
    if (k == 0) return 0;
    if (k > n / 2) return -1;
    long[] cost = new long[n];
    for (int i = 0; i < n; i++) {
      int prev = nums[(i - 1 + n) % n], next = nums[(i + 1) % n];
      cost[i] = Math.max(0, Math.max(prev, next) + 1L - nums[i]);
    }
    long best = linear(cost, 1, n - 1, k);
    if (k >= 1) best = Math.min(best, cost[0] + linear(cost, 2, n - 2, k - 1));
    return best >= Long.MAX_VALUE / 4 ? -1 : (int) best;
  }
}
